                hydration_hooks=None, **handlers):
        delimiters = (self.PREFIX, self.SUFFIX)
        message = '' if self.message else None
        offset = 0 if self.offset is None else self.offset

        while True:
            if not ((0 <= n <= len(message)) or n == -1):  # -1 means all
                raise ValueError('n should be non-negative or -1\n')
            s = message.find(delimiters[0], offset)
            if s >= 0:
                e = message.find(delimiters[1], s + 1)
                if e == -1:
                    raise ValueError('missing delimiter')
                self.delivery_handler.on_delivery(self.delivery_info, self.msg[s + 1:e])
                message = message[e + 1:]
                offset = 0
