def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    if mode is None and bookmarks is not None:
        handlers["commit"] = bookmarks
    elif mode is None and bookmarks is None:
        handlers["begin"] = {"mode": "READ"}
        mode = "READ"
    elif mode is not None:
        handlers["begin"] = {"mode": mode}
    else:
        handlers["begin"] = {"meta": metadata}
        mode = "WRITE"

    if handlers.get("commit", None) is not None:
        if bookmarks is not None:
            handlers["commit"].update({"bookmarks": bookmarks})
        if mode == "READ":
            handlers["commit"].update({"timeout": timeout})
        if db is not None:
            handlers["commit"].update({"db": db})
        if imp_user is not None:
            handlers["commit"].update({"imp_user": imp_user})
        if dehydration_hooks is not None:
            handlers["commit"].update({"dehydration_hooks": dehydration_hooks})
        if hydration_hooks is not None:
            handlers["commit"].update({"hydration_hooks": hydration_hooks})
        if timeout is not None:
            handlers["commit"].update({"timeout": timeout})

        return Response(*self.enqueue(PAYLOAD.BEGIN, payload=handlers["commit"]))
