def point_type(name, fields, srid_map):
    class _Point:
        __slots__ = ()
        def __new__(cls, *args):
            if len(args) > 2 or len(args) < 1:
                raise ValueError('Exactly 1 or 3 values must be provided')
            self = cls.__new__(cls)
            if len(args) == 2:
                x, y = args
            else:
                x, y, z = args
            self.x = x
            self.y = y
            self.z = z
            return self

        def __repr__(self):
            return f"Point(x={self.x}, y={self.y}, z={self.z})"

    class _PointMeta(type):
        def __new__(cls, *args, **kwargs):
            if len(args) != 2:
                raise ValueError('Exactly 2 arguments must be provided: PointMeta class and base class')
            base_class, _ = args
            new_class = super().__new__(cls, name, bsuple((base_class,), {}), {}, lambda ns: ns.update(kwargs))
            return new_class

    BaseClass = point_type('BasePoint', fields, srid_map)((),)
    MetaClass = _PointMeta('PointMeta', (BaseClass,), {})

    return BaseClass, MetaClass
