def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    new_cmd = []
    for part in cmd:
        if is_win_shell_script_path(part):
            new_cmd.append('"{part}"'.format(part=part))
        else:
            new_cmd.append(part)
    return tuple(new_cmd)

def is_win_shell_script_path(path: str) -> bool:
    """Check if the given path is a valid Python shebang or a deep-path shebang."""
    is_shell_script = path.startswith('#!')
    if is_shell_script:
        path = path[2:]
        is_deep_path = path.startswith('" "') or path.endswith('" "') or path.startswith('" '
                                                                                      ) or path.endswith(' "')
        if is_deep_path:
            return True
    return False
