            self.ttl_dict[key] = self.timer() + self.ttl * self.ttl_factor
            self.cache[key] = value
            self.keys.add(key)

        def invalidate(self, key):
            if key in self.cache:
                try:
                    del self.ttl_dict[key]
                    del self.cache[key]
                    del self.ttl_by_key[key]
                    del self.ttl_by_key_expire[key]
                except KeyError:
                    pass

