            keys_to_expire = list(set(self.ttl_by_key_expire.values()))
            now = self.timer()
            for expire_time in keys_to_expire:
                if now < expire_time:
                    if expire_time in self.ttl_by_key:
                        keys = self.ttl_by_key[expire_time]
                        self.invalidate(keys[0])
                        del self.ttl_by_key[expire_time]
                        del self.ttl_by_key_expire[expire_time]
