    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.

    """
    def decorator(func):
        if maxsize <= 0:
            return func

        cache = OrderedDict()
        time_start = timer()

        def wrapper(*args, **kwargs):
            key = (args, kwargs)
            if key in cache:
                cached_time = cache[key][0]
                if cached_time + ttl <= time_start:
                    del cache[key]
            if len(cache) >= maxsize:
                earliest_time, earliest_key = min(cache.items(), key=lambda x: x[1][0])
                del cache[earliest_key]
            cache[key] = (time_start, func(*args, **kwargs))
            return cache[key][1]

        @functools.wraps(func)
        def put(*args, **kwargs):
            key = (args, kwargs)
            if key in cache:
                cache[key][0] = time_start  # Update TTL

        @functools.wraps(func)
        def forget(*args, **kwargs):
            key = (args, kwargs)
            if key in cache:
                del cache[key]

        @functools.wraps(func)
        def clear():
            cache.clear()

        wrapper.put = put
        wrapper.forget = forget
        wrapper.clear = clear

        return wrapper

    return decorator
