    def extostr(cls, e, max_level=30, max_path_level=5):
        def format_exc(e):
            tb = sys.exc_info()[2]
            tbinfo = traceback.extract_tb(tb)
            path, line, name, src = '', '', '', None
            if tbinfo:
                path, line, name, src = tbinfo[-1]
            retd = {
                'msg': str(e),
                'file': path,
                'line': line,
                'name': name,
                'src': src
            }

            if isinstance(e, s_exc.SynErr):
                retd['syn:err'] = e.errinfo

            return retd

        if not isinstance(e, Exception):
            raise ValueError("Input must be an Exception instance")

        if max_level < 0:
            raise ValueError("max_level must be non-negative")

        if max_path_level < 0:
            raise ValueError("max_path_level must be non-negative")

        if max_level > 100:
            raise ValueError("max_level cannot exceed 100")

        if max_path_level > 20:
            raise ValueError("max_path_level cannot exceed 20")

        if max_level < max_path_level + 1:
            raise ValueError("max_path_level must be less than max_level")

        if len(e.args) > 3:
            raise ValueError("Too many arguments passed to extostr")

        if len(e.args) < 3:
            raise ValueError("Not enough arguments passed to extostr")

        exc_type, exc_value, exc_traceback = e.args

        if isinstance(exc_type, str):
            exc_info = exc_type, str(exc_value), exc_traceback
            exc_type = "Exception"
        elif isinstance(exc_type, tuple):
            exc_info = exc_type + (exc_value, exc_traceback)
            exc_type = "Exception"
        else:
            raise ValueError("Invalid type for exc_type")

        if isinstance(exc_value, str):
            exc_value = exc_info[1]

        if isinstance(exc_traceback, str):
            exc_traceback = exc_info[2]

        if len(e.args) == 3:
            return format_exc(exc_info)

        if len(e.args) == 4:
            max_level = e.args[3]
        if len(e.args) == 5:
            max_path_level = e.args[4]

