from typing import Any, Tuple, Dict

def extostr(cls, e: Any, max_level: int = 30, max_path_level: int = 5) -> str:
    tb = sys.exc_info()[2]
    tbinfo = traceback.extract_tb(tb)
    path, line, name, src = '', '', '', None
    if tbinfo:
        path, line, name, src = tbinfo[-1]
    retd = {
        'msg': str(e),
        'file': path,
        'line': line,
        'name': name,
        'src': src
    }

    call_stack = traceback.extract_stack(limit=max_level)
    if call_stack:
        call stack_filter = filter(lambda x: x[1] != cls.__file__, call_stack)
        call_stack = list(call_stack_filter)

        path, line, name, src = call_stack[-1]
        if max_path_level >= 0:
            retd['from'] = f'{path}:{line}:{name}'

    if isinstance(e, s_exc.SynErr):
        retd['syn:err'] = e.errinfo

    return str(e) + " - " + str(retd)
