    def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Handle error indices
        errors = self erroneous_edge_transactions
        error_data = have_'x'_'y'_'z' in self.__dict__
        if error_data:
            for el in errors:
                try:
                    context['error'] = []
                    context['error'].append(
                        {
                            'x': el['x'], 'y': el['y'], 'z': el['z'],
                            'index': errors.index(el)
                        })
                except KeyError:
                    pass
        else:
            context['error'] = []

        # Handle additional context properties
        # Update context with the properties of this graph
        for prop_name in dir(self):
            if prop_name.startswith("__"):
                continue
            prop_value = getattr(self, prop_name)
            if not isinstance(prop_value, (int, float, str, bool, list)):
                continue

            # Skip properties that are sub-contexts
            if isinstance(prop_value, dict):
                continue

            # Initialize value if not already present
            if prop_name not in context:
                context[prop_name] = prop_value
            else:
                if isinstance(context[prop_name], list):
                    context[prop_name].append(prop_value)
                else:
                    context[prop_name] = [context[prop_name], prop_value]

