import re
from django.core.exceptions import ValidationError

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expressions. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    regex_list = {
        "key1": r"^[a-zA-Z][a-zA-Z0-9]*$",
        "key2": r"^[a-zA-Z][a-zA-Z0-9]*$",
        "key3": r"^[a-zA-Z][a-zA-Z0-9]*$",
        "key4": r"^[a-zA-Z][a-zA-Z0-9]*$",
        "$$": r"^[a-zA-Z]"
    }

    error_messages = []
    for key, value in labels.items():
        if type(value) not in [str, list]:
            error_messages.append({"key": key, "value": "expected string or bytes-like object"})
        else:
            if isinstance(value, list):
                for val in value:
                    if not isinstance(val, str):
                        error_messages.append({"key": key, "value": f"['{val}'] expected string or bytes-like object"})
            else:
                if not re.match(regex_list[key], value):
                    error_messages.append({"key": key, "value": f"Label key '{key}' does not match the regex {regex_list[key]}"})

    if error_messages:
        raise ValidationError(error_messages)

