def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    spec = app.spec
    default_schemas = {}

    for resource in spec.manifest:
        # Get the Kubernetes API class
        api = getattr(kubernetes, resource + 'Api')

        # Check if a custom observer schema is already specified
        if not hasattr(app, 'custom_observers') or not app.custom_observers.get(resource):
            # Generate the default observer schema
            default_observer_schema = {
                'type': dict,
                'properties': {
                    'message': {'type': str},
                    'timestamp': {'type': 'date-time'},
                    'metadata': {
                        'type': dict,
                        'properties': {
                            'name': {'type': str},
                            'namespace': {'type': str},
                            'resource_type': {'type': 'string'}
                        }
                    }
                },
                'required': ['message', 'timestamp', 'metadata']
            }

            # Add the default observer schema to the dictionary
            default_schemas[resource] = default_observer_schema
    return default_schemas
