def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    required_schemas = {'ConfigMap': {}, 'Secret': {}}
    default_observer_schemas = {}

    # Parse spec.manifest to retrieve required schema for each resource
    for resource_type in app.manifest:
        if resource_type in required_schemas:
            for metadata in resource_type['metadata']:
                if 'name' in metadata:
                    name = metadata['name']
                    default_observer_schema = app.default_observer_schemas.get(name)
                    if default_observer_schema:
                        required_schemas[resource_type][name] = default_observer_schema

    # Combine required schemas with default observer schemas
    for resource_type, resources in required_schemas.items():
        for name, config in resources.items():
            if config is None:
                config = app.default_observer_schemas.get(name)
            default_observer_schemas[resource_type][name] = config

    return default_observer_schemas
