from typing import AnyStr, Dict, Union, Sequence, Tuple

def format(
  self,
  sql: AnyStr,
  params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
  if not self.sql_params.in_style in self.sql_params.valid_in_style:
    raise ValueError(f"The in-style {self.sql_params.in_style} is not valid.")
  if self.sql_params.in_style == 'named':
    if not isinstance(params, dict):
      raise ValueError(f"The in-style parameter keyword arguments must be a dictionary.")
    # Convert the dictionary of in-style parameters into a tuple of out-style parameters.
    out_params = tuple(v for k, v in params.items())
  else:
    if not isinstance(params, Sequence):
      raise ValueError(f"The in-style parameter sequence must be a sequence.")
    # Convert the sequence of in-style parameters into a tuple of out-style parameters.
    out_params = tuple(params)
  # Format the SQL query by replacing the in-style parameters with out-style parameters.
  formatted_sql = sql.format(out_params)
  return formatted_sql, out_params
