def formatmany(self, sql, many_params):
    if isinstance(many_params, Mapping):
        out_params = [tuple(val) for val in many_params.values()]
    elif isinstance(many_params, Sequence):
        out_params = [tuple(val) for val in many_params]
    else:
        raise TypeError("many_params should be a dict or a list")

    formatted_sql = sql % {f"%{i+1}%": p for i, p in enumerate(out_params)}
    return formatted_sql, out_params
