def validate(self, inventory, extract_spec_version=False):
    if type(inventory) != dict:
        raise TypeError(f"Expected {type(dict)} input, but received {type(inventory)}")
    if extract_spec_version and 'type' not in inventory:
        raise ValueError("'type' is not present in the input inventory.")
    if extract_spec_version and 'version' not in inventory:
        inventory['version'] = self.spec_version

    # validate each item in the inventory
    for item_name, item in inventory.items():
        if type(item) == list:
            for idx, inner_item in enumerate(item):
                valid = self.item_type.validate(inner_item, item_name + "." + str(idx))
                item[idx] = valid
        else:
            valid = self.item_type.validate(item, item_name)
            inventory[item_name] = valid
