def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    # Check if all required digests are present
    digests_not_found = []
    for manifest_file in manifest_files:
        manifest_entry = manifest_file.get('digest')
        if manifest_entry not in digests_used:
            digests_not_found.append(manifest_entry)

    if digests_not_found:
        raise RuntimeError(f"Missing digests in manifest: {digests_not_found}")

    # Check if all required digests are used
    digests_not_used = []
    for digest in digests_used:
        if digest not in self.analyzed_files:
            digests_not_used.append(digest)

    if digests_not_used:
        raise RuntimeError(f"Unused digests: {digests_not_used}")
