def get_logical_path_map(inventory, version):
    '''Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    '''

    logical_map = {}

    for content in inventory:
        if content['version'] <= version:
            logical_path = f"{inventory.index(content) + 1}_{content['filename']}"
            content_files = set()
            for file_key in content:
                if file_key.endswith(".index"):
                    index_file_path = f"{inventory.index(content) + 1}_{content[file_key]}"
                    content_files.add(index_file_path)
                else:
                    content_files.add(file_key)

            logical_map[logical_path] = content_files

    return logical_map
