def _extract_number_and_supplment_from_issue_element(issue):
    numbers = {}
    suppls = {}

    for match in re.finditer(r'(\d+)([A-Z\S\s]*)', issue):
        number = match.group(1)
        supplement = match.group(2)

        numbers[number] = supplement
        suppls[supplement] = number

