def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Args:
        indent (int): The number of spaces to use for indentation. Defaults to 0.
        debug (bool): If True, include debug information. Defaults to False.

    Returns:
        str: A pretty formatted string representation of self.
    """
    class NodePrinter:
        def __init__(self, indent):
            self.indentation = indent

        def node(self, node):
            """ Pretty print a node """
            raise NotImplementedError

        def block(self, block):
            """ Pretty print a block of nodes """
            raise NotImplementedError

        def numeric(self, numeric):
            """ Pretty print a numeric value """
            raise NotImplementedError

        def string(self, string):
            """ Pretty print a string value """
            raise NotImplementedError

        def key(self, key):
            """ Pretty print a key """
            raise NotImplementedError

        def value(self, value):
            """ Pretty print a value """
            raise NotImplementedError

        def comment(self, comment):
            """ Pretty print a comment """
            raise NotImplementedError

        def print(self, obj):
            """ Print an object """
            if isinstance(obj, Node):
                self.node(obj)
            elif isinstance(obj, list):
                if debug:
                    print(f"({len(obj)} items)")
                self.block(obj)
            elif isinstance(obj, str):
                self.string(obj)
            elif isinstance(obj, dict):
                if debug:
                    print(f"{len(obj)} properties")
                sort_keys = sorted(obj.items()) if debug else obj.items()
                block = ['\t' * self.indentation + f"{key}: {value}" for key, value in sort_keys]
                self.block(block)
            elif isinstance(obj, int) or isinstance(obj, float):
                self.numeric(obj)
            elif isinstance(obj, bool):
                self.numeric(obj)
            elif isinstance(obj, dict):
                self.comment(f"comment: {obj['comment']}")
            else:
                self.string(str(obj))

