            for node in block:
                node_string = self.print(node)
                if node_string:
                    line.append(node_string)
            return '\n'.join(line)

        def node(self, node):
            """ Pretty print a node """
            if isinstance(node, Esp5Function):
                self.string(f"function {node.name}({node.args}){{\n")
                for block in node.blocks:
                    self.block(block)
                self.string("}}")
            elif isinstance(node, Esp5Variable):
                self.string(f"const {node.name} = {self.print(node.value)};")
            elif isinstance(node, Esp5Expression):
                self.string(f"{self.print(node.value)}")
            elif isinstance(node, Esp5Switch):
                self.string("switch({}){{\n")
                for case in node.cases:
                    self.string(f"  {case.value}:{{\n")
                    for chunk in case.chunks:
                        self.block([chunk])
                    self.string("  }}")
                self.string("}}")
            elif isinstance(node, Esp5If):
                self.string("if({}){{\n")
                self.block(node.blocks[0])
                self.string("}}")
            elif isinstance(node, Esp5Return):
                self.string(f"return {self.print(node.value)};")
            elif isinstance(node, Esp5Throw):
                self.string(f"throw {self.print(node.value)};")
            elif isinstance(node, Esp5Array):
                self.string(f"[{', '.join(self.print(item) for item in node.items)}]")
            elif isinstance(node, Esp5Object):
                sort_keys = sorted(node.items()) if debug else node.items()
                block = ['\t' * self.indentation + f"{key}: {self.print(value)}" for key, value in sort_keys]
                self.block(block)
            elif isinstance(node, Esp5AnonFunction):
                self.string(f"({node.args}) => {\n")
                for func_block in node.func_blocks:
                    self.block(func_block)
                self.string("}")
            elif isinstance(node, Esp5This):
                self.string("this")
            elif isinstance(node, Esp5Extends):
                self.string(f"extends {self.print(node.name)}")
            elif isinstance(node, Esp5Import):
                self.string(f"import {self.print(node.name)};")
            elif isinstance(node, Esp5Export):
                self.string(f"export {self.print(node.name)};")
            elif isinstance(node, Esp5ImportDefault):
                self.string(f"import {self.print(node.name)} from '{self.print(node.module)}';")
            elif isinstance(node, Esp5ExportDefault):
                self.string(f"export default {self.print(node.name)};")
            elif isinstance(node, Esp5ConditionalExpression):
                self.string(f"({self.print(node.test)}) ? {self.print(node.consequent)} : {self.print(node.alternate)}")
            elif isinstance(node, Esp5UnaryOperator):
                self.string(f"{self.print(node.value)} {self.print(node.operator)}")
            elif isinstance(node, Esp5BinaryOperator):
                self.string(f"{self.print(node.left)} {self.print(node.operator)} {self.print(node.right)}")
            elif isinstance(node, Esp5SpecialOp):
                self.string(f"{self.print(node.name)}")
            else:
                self.string(str(node))

    def print(self, obj):
        if isinstance(obj, Esp5Node):
            return Esp5NodePrinter(self.indentation).print(obj)
        return str(obj)

    return self.print(self)
