def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def absorb_check(a, b):
        return a & (a | b) == a or a | (a & b) == a

    def negative_absorb_check(a, b):
        return a & (~a | b) == a & b or a | (~a | b) == a | b

    def apply_operations(args):
        result = []
        for arg in args:
            if '=' in arg:
                key, value = arg.split('=')
                value = value.strip()
                if key == 'absorption':
                    result.append(absorb_check)
                elif key == 'negative_absorption':
                    result.append(negative_absorb_check)
            else:
                value = arg.strip()
                result.append(lambda x: x == value)
        return result

    ops = apply_operations(args)
    def filter_expressions(expr):
        if isinstance(expr, (list, tuple)):
            return [filter_expressions(e) for e in expr]
        elif isinstance(expr, bool):
            return expr
        return any(op(expr) for op in ops)
    return [expr for expr in self.expressions if filter_expressions(expr)]
