    def _fromutc(self, dt):
        """
        Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in a new timezone.

        Since this is the one time that we *know* we have an unambiguous
        datetime object, we take this opportunity to determine whether the
        datetime is ambiguous and in a "fold" state (e.g. if it's the first
        occurrence, chronologically, of the ambiguous datetime).

        :param dt:
            A timezone-aware :class:`datetime.datetime` object.
        """
        if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
            raise ValueError("Invalid timezone object")

        # Calculate the new timezone
        new_tz = self.new_tz

        # Get the offset of the new timezone
        new_offset = new_tz.utcoffset(dt)

        # If the new timezone is the same as the original timezone,
        # the datetime is not ambiguous and in a "fold" state
        if new_offset == dt.utcoffset(dt):
            # If the new timezone is UTC, we use pytz localtimezone
            if new_offset == timedelta(hours=0):
                return dt.astimezone(localtz())
            else:
                return dt.astimezone(new_tz)
        else:
            # If the new timezone is not UTC, we use pytz timezone
            return dt.astimezone(new_tz)
