import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: The command or commands to execute. Can be a single string or a list of strings.
    :param args: The arguments to pass to the command.
    :param cwd: The working directory for running the command. Defaults to the current working directory.
    :param verbose: Whether to show verbose output. Defaults to False.
    :param hide_stderr: Whether to hide the standard error output. Defaults to False.
    :param env: environment variables to pass to the command. Defaults to None.
    """
    output = None
    try:
        if isinstance(commands, str):
            commands = [commands]

        for index, command in enumerate(commands):
            cmd_args = [command]

            # Add arguments to the command list if provided
            if args:
                cmd_args.extend(args)

            # Execute the command
            if cwd:
                cmd_args.append(f'-cd {cwd}')

            if verbose:
                print(f'Executing command {index + 1}: {" ".join(cmd_args)}')
            else:
                print(f'Executing command {index + 1}:', end='')

            # Set environment variables if provided
            if env:
                cmd_args.extend(['-e', f'{key}="{value}"' for key, value in env.items()])

            cmd_process = subprocess.Popen(cmd_args, stdout=subprocess.PIPE, stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL, env=env)
            cmd_output, cmd_error = cmd_process.communicate()

            if cmd_process.returncode != 0:
                output = {}
                output['error'] = cmd_error.decode('utf-8')
            else:
                output = {'stdout': cmd_output.decode('utf-8'), 'stderr': cmd_error.decode('utf-8')}

            if verbose:
                if output['stdout']:
                    print(output['stdout'], end='')
                if output['stderr']:
                    print(output['stderr'])
    except Exception as e:
        print(f'Error in running command: {e}')
        output = {}

    return output
