    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    if not validate_objects and not check_digests and not show_warnings:
        return 0, 0

    total_objects = 0
    good_objects = 0

    current_node = self._root_node
    while current_node:
        total_objects += 1
        if validate_objects or check_digests or show_warnings:
            if not current_node.validate(check_digests, self._storage_service):
                if show_warnings:
                    print(f"Warning: Invalid object found at path '{current_node.path}'.")
            else:
                good_objects += 1
        current_node = current_node.get_child_path(self._ hierarchy_path)

    return total_objects, good_objects
