def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise TypeError('version_dirs must be a list of version directory names.')

    for i, version_dir in enumerate(version_dirs):
        if not version_dir:
            raise ValueError('version_dirs must not be empty.')

        if i >= 1 and version_dirs[i - 1] >= version_dir:
            raise ValueError(f'Each version in version_dirs should be greater than the previous one, but {version_dirs[i - 1]} >= {version_dir}')

        inventory_file = os.path.join(self.package_dir,.version_dir, 'inventory')
        if not os.path.exists(inventory_file):
            raise FileNotFoundError(f'Inventory file not found for version {version_dir}.')

    return True
