def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    Digests = {}

    for version in version_dirs:
        inventory_file = f"{version}/inventory"
        try:
            with open(inventory_file, 'r') as h:
                inventory = h.read().splitlines()
                Digests[version] = inventory
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file for version {version} not found.")

    root_inventory_file = "root_inventory"
    try:
        with open(root_inventory_file, 'r') as h:
            root_inventory = h.read().splitlines()
            for version in version_dirs:
                if version not in root_inventory:
                    new_digest = []
                    for line in root_inventory:
                        line_items = line.split()
                        if len(line_items) == 2:
                            if int(line_items[1]) <= int(version):
                                new_digest.append(line)
                            else:
                                new_digest.append(line + "\n")
                    with open(f"{version}/inventory", 'w') as dig_file:
                        for line in new_digest:
                            dig_file.write(line)
                    Digests[version] = new_digest
    except FileNotFoundError:
        raise FileNotFoundError(f"Root inventory file not found.")
