from packaging.specifiers import InvalidSpecifier
from packaging.core import Version

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    if not version_dirs:
        raise ValueError('version_dirs must be a non-empty list.')

    local_inventory = False
    inventories = []

    for version_dir in version_dirs:
        if version_dir.startswith('local'):
            local_inventory = True
            break
        else:
            version = Version(version_dir)
            if not isinstance(version, Version):
                raise ValueError(f'Invalid version: {version_dir}')
            inventories.append(version_dir)

    if not inventories:
        raise ValueError('No sorted version directories found.')

    if not local_inventory:
        raise ValueError('Local inventory not found in the list of version directories.')

    inventory_dirs = [local_inventory] + inventories

    for idx, parent_inventory in enumerate(inventory_dirs):
        child_inventory = inventory_dirs[idx + 1] if idx + 1 < len(inventory_dirs) else None

        if child_inventory is None:
            break

        if not parent_inventory.startswith(child_inventory):
            raise ValueError(f'Inventory {child_inventory} must come after {parent_inventory}')

    return inventory_dirs
