def amend_bzparams(self, params, bug_ids):
    """
        Amend the Bugzilla params

        >>> bzparams = {'product': 'OS', 'status': 'NEW'}
        >>> is_valid, off_indices, off_warnings = bzparams amender(bzparams= bzparams, bug_ids= [1234567])
        >>> print(is_valid, off_indices, off_warnings)
        (True, [], [])
    """
    import json
    from requests.exceptions import RequestException

    for bug_id in bug_ids:
        url = f"https://bugzilla.mozilla.org/rest/bug/{bug_id}"
        headers = {
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {self.auth}'
        }
        try:
            response = requests.get(url, headers=headers)
            response.raise_for_status()
            bug_data = response.json()
        except RequestException as e:
            print(f"Failed to fetch bug data for {bug_id}: {e}")
            raise

        for k, value in params.items():
            if k in bug_data:
                if isinstance(value, dict):
                    # If the value is a dictionary representing a list of objects, update the entire list
                    bug_data[k] = [{**b, 'field': f'{self.alias}{k}'} for b in bug_data[k]]
                else:
                    # If it's a simple dictionary mapping attribute keys to values, update the corresponding attribute
                    bug_data[k] = {f'{self.alias}{k}': value}
            else:
                # If the key is not in the bug data, ignore it
                continue

        # Update the bug in Bugzilla with the new parameters
        response = requests.put(url, headers=headers, json=bug_data)
        response.raise_for_status()

        print(f"Successfully updated bug {bug_id}")
