def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = []

    for argument in parsed_arguments:
        for subparser_name, parser in subparsers.items():
            try:
                result = parser.parse_known_args([argument])
                if result[1]:
                    remaining_arguments.extend(result[1])
                parsed_arguments[subparser_name] = result[0]
                break
            except Exception as e:
                print(f"Failed to parse subparser {subparser_name}: {e}")
                # Move to the next argument
                continue

    return parsed_arguments, remaining_arguments
