def bash_completion():
    """Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    commands = [
        arg(choices=('list', 'delete', 'patch', 'prune', 'status', 'setup',
                     'upgrade', 'version'), help='Command to complete')
    ]

    completers = []
    for command in commands:
        if command.is_flag:
            completers.append(command.name.lstrip('-'))
        else:
            completers.extend([opt.lstrip('-') for opt in command.opts])

    return ' '.join([f'"{com}"' for com in completers])
