def parse_link_value(headers: str) -> Dict[str, Dict[str, Optional[str]]]:
    links = {}
    if headers and "Link" in headers:
        for link in headers["Link"].strip().split(";"):
            link_parts = link.strip().split(",")
            url, params = link_parts.pop().strip(), link_parts[:-1]
            params_dict = {}
            for param in params:
                key, value = param.strip().split("=", 1)
                params_dict[key] = value.strip('"')
            links[url.strip()] = params_dict
    return links

def paging(response: List[HTTPResponse], max_results: int) -> List[HTTPResponse]:
    result = []
    for item in response:
        current_page = type(item)()
        current_page.after = After(max_results)
        current_page.before = Before()
        result.append(current_page)
    return result
