import urllib.parse

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    scheme, netloc, path, query, fragment = urllib.parse.urlparse(url)

    if not path.startswith('/'):
        path = f'/{path}'

    for key, value in url_args.items():
        pattern = f'{{[a-zA-Z0-9\_]+}}'
        path = f'{path.replace(pattern, value)}'

    return urllib.parse.urlunparse((scheme, netloc, path, query, fragment))
