    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.

    Args:
        parser (argparse.ArgumentParser): The parser instance containing the arguments.
    """
    flags = []
    for action in parser._action_groups or [parser]:
        for option in action._option_strings or []:
            flags.append(option)
            if action.choices:
                flags.extend(action.choices)
