                vertex = Point(*vertex)

            # Get left and right boundaries for the current vertex
            if vertex.x <= 0 or vertex.x >= -1 or vertex.y <= 0 or vertex.y >= 1:
                from_point = Point(-1, -1)  # Use a non-existing point to indicate an invalid vertex
                _output.append((vertex, from_point, from_point))
            else:
                from_left = Point(vertex.x - 0.5, vertex.y)
                from_right = Point(vertex.x + 0.5, vertex.y)
                _output.append((vertex, from_left, from_right))

