def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    base = len(alphabet)
    if number < 0:
        result = "-" + int_to_string(-number, alphabet, padding)
        return result

    if padding is None:
        if number < base:
            return alphabet [number]
        else:
            lengths = [len(alphabet[c]) for c in str(number)]
            pad = max(lengths) - len(str(number))
            return alphabet[number] + ("0" * pad)
    else:
        if number < base:
            return alphabet[number]
        else:
            lengths = [len(alphabet[c]) for c in str(number)]
            if len(lengths) > padding:
                padding = 0
            pad = padding - len(str(number))
            return alphabet[number] + ("0" * pad)
