                result = []
                i = 0
                while i < len(data):
                    if data[i:i+len(sep)] == sep:
                        result.append(data[i:len(sep)])
                        i += len(sep)
                    elif i == len(data) - len(sep):
                        result.append(data[i:])
                        i += len(sep)
                    else:
                        i += 1
                return result
            re.splitl = splitl
        normfunc = re.splitl
    elif platform == 0:
