        splitfunc = lambda x,sep,b=bytes([]): [x[idx+1:].replace(b,sep[idx],1).replace(b,sep[idx+1:],1) for idx in range(len(sep))]
    elif platform == 1:
        # Shlex on Posix
        import shlex
        splitfunc = shlex.split
