def subprocess_run_helper(func, *args, timeout=None, extra_env=None):
    """
    Run a function in a sub-process.

    Parameters
    ----------
    func : function
        The function to be run.  It must be in a module that is importable.
    *args : str
        Any additional command line arguments to be passed in
        the first argument to ``subprocess.run``.
    timeout : int
        Timeout in seconds for the subprocess to complete.
    extra_env : dict[str, str]
        Any additional environment variables to be set for the subprocess.
    """
    try:
        if timeout:
            kwargs = {"timeout": timeout}
            if extra_env:
                kwargs["env"] = extra_env
            result = subprocess.run([func] + list(args), **kwargs)
        else:
            result = subprocess.run([func] + list(args))
        if result.returncode != 0:
            raise subprocess.CalledProcessError(result.returncode, f"Failed to {func} with args {args}")
        return result.stdout.decode('utf-8')
    except FileNotFoundError:
        raise FileNotFoundError(f"Module {func} not found")
    except subprocess.CalledProcessError as e:
        raise subprocess.CalledProcessError(e.returncode, f"Failed to run {func} with args {args}\n{e.stderr.decode('utf-8')}")
    except subprocess.TimeoutExpired as e:
        raise subprocess.TimeoutExpired(f"Command {func} timed out after {e.timeout} seconds")
    except Exception as e:
        raise Exception(f"An error occurred while running {func} with args {args}\n{str(e)}")
