from subprocess import run
from typing import Callable, Any

def subprocess_run_helper(func: Callable[..., Any], *args: str, timeout: float | None = None, extra_env: dict[str, str] | None = None) -> subprocess.CompletedProcess:
    if extra_env is None:
        extra_env = {}

    try:
        result = run((func.__module__, func.__name__, *args) if isinstance(func, Callable) else [func] + args,
                        executable=subprocess.executable,
                        check=True,
                        timeout=timeout,
                        env={**os.environ, **extra_env})
        return result
    except subprocess.CalledProcessError as e:
        if timeout is not None:
            print(f"Error: Timeout of {timeout:.2f} seconds exceeded during subprocess execution.")
            if e.stderr:
                print(f"Error output: {e.stderr.decode()}")
        else:
            print(f"Error: Failed to execute function: {e}")
            if e.stderr:
                print(f"Error output: {e.stderr.decode()}")
