            print(f"Running command: {' '.join([cmd for cmd in commands for args in args])}")

        output = subprocess.run(
            commands,
            args=args,
            cwd=cwd,
            capture_output=(not hide_stderr),
            text=True,
            env=env,
        )

        if output.stderr:
            if verbose:
                print(f" stderr: {output.stderr}")
                return output.stderr, None

        if output.stdout:
            if verbose:
                print(f" stdout: {output.stdout}")
            return None, output.stdout

        return None, None

    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Error: {e}")
