from rdflib import Graph, URIRef
from typing import Optional, Set

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    current_roots = set(graph.objects(subject=digraph, predicate=prop))
    if len(current_roots) == 0:
        return set()
    remaining_roots = current_roots - roots
    seen_roots = current_roots
    while remaining_roots:
        new_roots = {o.subject for o in graph.objects(subject=remaining_roots, predicate=prop)}
        seen_roots.update(new_roots)
        remaining_roots = remaining_roots - new_roots
    return seen_roots
