def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    results = {}
    errors = []
    for filename in config_filenames:
        try:
            with open(filename, 'r') as fd:
                config = yaml.safe_load(fd)
                results[filename] = config
        except yaml.YAMLError as e:
            log.error(f"Error loading {filename}: {e}")
            errors.append(logging.LogRecord(f"load_configurations: {filename}", logging.ERROR, __name__, 0, traceback.format_exc(), None, None))

    if overrides:
        for override_file, override_dict in overrides.items():
            results[override_file] = override_dict

    if resolve_env:
        for filename, config in results.items():
            if 'environment' in config:
                config['environment'] = os.getenv(config['environment'])

    return results, errors
