        raise HandledError
    if config['tag'] and not re.match(REGEX_GENERAL, config['tag']):
        log.error('Invalid git tag obtained.')
        raise HandledError

def _configure_logging(logger_dict: Optional[dict]) -> None:
    if logger_dict is None:
        log.debug("No logger dictionary defined. Doing default logger configuration")
        formatter = logging.Formatter("%(name)s - %(asctime)s - [%(levelname)s] - %(module)s - %(message)s")
        stream_handler = logging.StreamHandler(sys.stdout)
        stream_handler.setLevel(logging.WARNING)
        stream_handler.setFormatter(formatter)
        logging.getLogger().addHandler(stream_handler)
        logging.getLogger().setLevel(logging.WARNING)
    else:
        log.debug("Logger dictionary defined. Loading dictConfig for logging")
        dictConfig(logger_dict)

def load_configurations(config_filenames: List[str], overrides: Optional[List[str]] = None, resolve_env: bool = True) -> Tuple[dict, List[logging.LogRecord]]:
    configured_logs: dict = {}
    parsed_errors: List[logging.LogRecord] = []

    for conf_filename in config_filenames:
        try:
            log = logging.getLogger(conf_filename)
            config_dict = _load_config(conf_filename, overrides, resolve_env)
            data = _validate_config(config_dict, log)
            configured_logs[conf_filename] = {'config': data, 'parsed_errors': []}
        except ValidationError as ve:
            parsed_errors.append(ve)
        except FileNotFoundError as fnfe:
            parsed_errors.append(fnfe)

