def determineMetaclass(bases, explicit_mc=None):
    stack = []
    stack.append(bases)
    metaclass_values = set()
    while stack:
        current_bases = stack.pop(-1)
        for base in current_bases:
            if isinstance(base, type):
                metaclass_values.add(base)
            elif isinstance(base, tuple) or isinstance(base, list):
