        min_usage_key = min(self._cache.items(), key=lambda x: x[1][1])[0]
        key, value = min_usage_key
        if value[0] == 'L':
            logger.debug('Least recently used value of %s is stale, updating usage', key)
            value[1] += 1
        else:
            logger.debug('Updating usage of value %s', key)
            value[1] = 1

        # Remove the stale key-value pair
        del self._cache[key]

        return (key, value[0])
