class Dictator:
    def __init__(self):
        self._dict = {}
        self._counts = defaultdict(int)

    def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""

        # Calculate the frequency of each key
        frequencies = {key: self._counts[key] for key in self._counts}

        # Find the key with the lowest frequency
        if not frequencies:
            raise KeyError('dictionary is empty')

        key, value = min(frequencies.items(), key=lambda x: x[1])[0]

        # Decrement the frequency of the removed key
        self._counts[key] -= 1

        return (key, value)
