    """Remove and return the `(key, value)` pair least recently used."""

    if self._head is None:
        raise KeyError('list is empty')

    to_pop = self._head
    if to_pop[1][2] is None:
        if to_pop is self._tail:
            self._head = self._tail = None
        else:
            self._head = to_pop[1]
            self._head[2] = self._tail
        return to_pop[0], to_pop[1][1]

    while to_pop[1][2] is not None:
        prev = to_pop
        to_pop = to_pop[1][2]

    if to_pop is self._tail:
        prev[1][2] = self._tail = None
    else:
        prev[1][2] = to_pop[1]
        to_pop[1][2] = None

    return to_pop[0], to_pop[1][1]
