from datetime import datetime

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    # Check if dt is already in the expected format
    if isinstance(dt, str):
        # Attempt to parse the string as a datetime
        try:
            dt = datetime.strptime(dt, "%Y-%m-%dT%H:%M:%SZ")
        except ValueError:
            # If parsing fails, return the input string as is
            return dt
    # Validate the format of datetime object
    if isinstance(dt, datetime) and dt.tzinfo is not None:
        # If datetime is local, return it as is
        if dt.tzinfo.utcoffset(None) == DEFAULT_TZ:
            return dt

    # Convert datetime object to ISO format if it is tz naive
    if not dt.tzinfo:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.strftime(DATETIME_ISO_FORMAT)
