def find_tags(text, replacer=None):
    r"""
    Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = []
    tags_set = set()
    text = text.splitlines()
    current_block_code = False
    for line in text:
        if current_block_code:
            if line.strip().startswith("</code>"):
                current_block_code = False
            continue
        if line.strip().startswith("```"):
            if line.strip() == "```cpp":
                continue  # Skip C++ block if tag is within it
            current_block_code = True
            continue
        if current_block_code:
            continue
        if not line.strip():
            continue
        parts = line.split()
        if len(parts) >= 1:
            current_tag = parts[0].strip()
            if current_tag.startswith("#"):
                if replacer is not None:
                    tags_set.add(replacer(current_tag))
                else:
                    tags_set.add(current_tag)
                tags.append(current_tag)
    return tags_set, ' '.join([' '.join(tags) if tags else text])
```

