import urllib.request
from typing import Optional

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        scheme, netloc, path, query, fragment = urllib.parse.urlsplit(url)
        if scheme not in ('http', 'https'):
            return None

        req = urllib.request.HeadRequest(url, headers={'Host': netloc})
        resp = urllib.request.urlopen(req, timeout=10)  # Set a timeout of 10 seconds for DNS resolution
        try:
            if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
                return None
            return resp.info().get('content-type', '')
        finally:
            resp.close()
    except urllib.error.URLError as e:
        print(f"Error fetching content type from {url}: {e}")
        return None
