def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    :param settings_dirs: iterable of directories containing configuration settings
    :param spec_option: specification options for the ini file
    :return: list of full file names found in the directories
    """
    file_names = []
    if isinstance(settings_dirs, list):
        for dir in settings_dirs:
            for file in os.listdir(dir):
                if file.endswith('.conf') or file.endswith('.ini'):
                    file_names.append(os.path.join(dir, file))
    else:
        file_names.append(os.path.join(settings_dirs, 'config.ini'))
    return file_names
