import yaml
from typing import Any, Dict

class IRValidatorException(Exception):
    def __init__(self, message: str):
        super().__init__(message)

def validate_from_content(cls, spec_content: Any) -> Dict[Any, Any]:
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Cannot load spec from content: spec_content is None")

    # Check if the 'required' field is present in the spec
    required_fields = set(spec.get('required', []))
    if not required_fields:
        raise IRValidatorException("Cannot validate spec: spec missing 'required' field")

    # Load the spec content
    try:
        spec_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Invalid YAML content in spec: {e.__str__()}")

    # Validate each required field exists in the loaded spec
    for field in required_fields:
        if field not in spec_data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in spec file")

    return spec_data
