def validate_from_file(self, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise InvalidInputError("yaml_file argument must be supplied")

    try:
        raw_yaml = self.load_yaml_file(yaml_file)

        record_data = raw_yaml.get('data')

        if record_data is None or record_data is dict:
            raise InvalidDataError("The file does not contain any data fields.")

        errors = []

        # validate each field
        for field in self.mandatory_fields:
            if field.name not in record_data or field.value not in record_data[field.name]:
                record_data[field.name] = {"value": field.value}
                errors.append({
                    'message': f"Mandatory field '{field.name}' not found in the file.",
                    'field': field.field_id,
                    'validation_type': 'mandatory'
                })

        # raise an exception for each error
        for error in errors:
            return self.raise_error(error)

        return record_data

    except FileNotFoundError:
        return self.raise_error({
            'message': f"The file '{yaml_file}' was not found",
            'file': yaml_file
        })
