def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    try:
        code = self.__class__.__code__
    except AttributeError:
        # Some built-in classes don't have __code__, __defaults__, etc.
        return {}
    pos_count = code.co_argcount
    arg_names = code.co_varnames
    arg_names = arg_names[:pos_count]
    defaults = self.__class__.__defaults__ or ()
    kwdefaults = self.__class__.__kwdefaults__
    res = dict(kwdefaults) if kwdefaults else {}
    pos_offset = pos_count - len(defaults)
    for name, value in zip(arg_names[pos_offset:], defaults):
        assert name not in res
        res[name] = value
    return res
