def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_when_args = [arg for arg, condition in options_spec if condition]
    required_args = {arg: False for arg in required_when_args}

    for arg, value in args.items():
        if arg in required_args and value:
            required_args[arg] = True

    required_args_list = [arg for arg, value in required_args.items() if value]
    return required_args_list
