def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if len(args) != 2:
        raise TypeError("There must be exactly two arguments, representing minimum and maximum values.")

    min_value, max_value = args

    if not (isinstance(min_value, (int, float)) and isinstance(max_value, (int, float))):
        raise TypeError("Both minimum and maximum values must be numbers.")

    if min_value >= max_value:
        raise ValueError("Minimum value must be less than the maximum value.")
