def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """

    if extra_vars is None:
        extra_vars = []
    extended_vars = vars_dict.copy()
    for extra_var in extra_vars:
        if extra_var in extended_vars:
            if not isinstance(extended_vars[extra_var], list):
                extended_vars[extra_var] = [extended_vars[extra_var]]
            if extra_var not in extended_vars[extra_var]:
                extended_vars[extra_var].append(extra_var)
        else:
            extended_vars[extra_var] = [extra_var]
    return extended_vars
