def get_plugin_spec_flatten_dict(plugin_dir):
    # Read the plugin spec file
    with open(plugin_dir / 'spec.yaml', 'r') as file:
        spec = yaml.safe_load(file)

    # Flatten the spec dictionary
    flatten_spec = {}
    for key, value in spec.items():
        if isinstance(value, dict):
            flatten_spec.update({f"{key}.{k}": v for k, v in value.items()})
        else:
            flatten_spec[key] = value

    return flatten_spec
